import os

os.environ.setdefault("HF_HUB_OFFLINE", "1")
os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")

import torch
from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR, local_files_only=True)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR, local_files_only=True)
model.eval()


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be a JSON object."}), 400

    text = data.get("text")
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string."}), 400

    inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=512)
    with torch.no_grad():
        logits = model(**inputs).logits[0]
    probs = torch.softmax(logits, dim=-1)

    scores = {model.config.id2label[i].lower(): float(probs[i]) for i in range(len(probs))}
    sentiment_label = max(scores, key=scores.get)

    return jsonify(
        {
            "sentiment": sentiment_label,
            "confidence": {
                "positive": scores.get("positive", 0.0),
                "negative": scores.get("negative", 0.0),
            },
        }
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

